def get_mock_user(idx: int = 0) -> Dict[str, Any]:
    """Retrieve mock user dictionary by index."""
    return dict(MOCK_USERS[idx % len(MOCK_USERS)])

def get_mock_tenant(idx: int = 0) -> Dict[str, Any]:
    """Retrieve mock tenant dictionary by index."""
    return dict(MOCK_TENANTS[idx % len(MOCK_TENANTS)])

def get_mock_permissions(resource: str = None) -> List[Dict[str, Any]]:
    """Retrieve list of permissions optionally filtered by resource."""
    if resource:
        return [p for p in MOCK_PERMISSIONS if p["resource"] == resource]
    return list(MOCK_PERMISSIONS)
